package io.busystack.busydata;

import io.busystack.busydata.protocol.*;
import io.busystack.busydata.results.*;
import io.busystack.busydata.schema.*;
import io.busystack.busydata.sessions.SessionRegistry;
import java.nio.file.Path;
import java.nio.file.Files;
import java.sql.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

/** Pinned PostgreSQL array retention, reviewed editing and exact native evidence. */
class ArrayEditingIT {
    @TempDir Path root;
    private static final String FIELDS="integers,numbers,texts,bytes,matrix,statuses,prices";
    private static Value integer(int value){return Value.newBuilder().setSignedInteger(Integer.toString(value)).build();}
    private static List<String> nativeValues(SessionRegistry.Session session,String table,int id)throws Exception {
        var values=new ArrayList<String>();
        try(var statement=session.connection.prepareStatement("SELECT integers::text,numbers::text,texts::text,bytes::text,matrix::text,statuses::text,prices::text FROM "+table+" WHERE id=?")){
            statement.setInt(1,id);try(var rows=statement.executeQuery()){assertTrue(rows.next());for(int i=1;i<=7;i++)values.add(rows.getString(i));assertFalse(rows.next());}
        }return values;
    }
    private static ChangeRequest request(SessionRegistry.Session session,ResultStore.Result source,StagedChange change){return ChangeRequest.newBuilder().setSessionId(session.id).setCatalog("busydata").setSchema("public").setTable("array_edit").setResultId(source.id).addChanges(change).build();}
    @Test void exactArraysParticipateInOriginalVerificationCloneRecoveryAndSqlCopy()throws Exception {
        try(var fixture=new EngineFixture(root,"POSTGRESQL")){
            var session=fixture.open();fixture.execute(session,"""
                CREATE TYPE status_type AS ENUM ('new','active');
                CREATE DOMAIN price_domain AS numeric(35,12) CHECK (VALUE >= 0);
                CREATE TABLE array_edit(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,n integer,
                  integers integer[],numbers numeric[],texts text[],bytes bytea[],matrix integer[][],
                  statuses status_type[],prices price_domain[]);
                INSERT INTO array_edit(n,integers,numbers,texts,bytes,matrix,statuses,prices) VALUES (
                  1, '[0:2]={1,NULL,3}'::integer[],
                  '[0:1]={12345678901234567890.123456789012,NULL}'::numeric[],
                  $txt$[0:2]={"漢😀","a\\\\b","quote'"}$txt$::text[],
                  ARRAY[decode('00ff','hex'),NULL,decode('7b7d5c','hex')],
                  '[-1:0][5:6]={{1,NULL},{3,4}}'::integer[],
                  '[0:1]={new,active}'::status_type[],
                  '[0:1]={1.230000000000,NULL}'::price_domain[]);
                """);
            var expected=nativeValues(session,"array_edit",1);
            fixture.warm(session,"array_edit");
            String table=session.adapter.table(session.context.catalog(),"public","array_edit");
            var source=fixture.results.get(fixture.execute(session,"SELECT id,n,"+FIELDS+" FROM "+table+" ORDER BY id").info().getResults(0).getResultId());
            var transfers=new io.busystack.busydata.transfers.Transfers(fixture.results);
            for(String format:List.of("csv","tsv","json","ndjson")){
                Path output=root.resolve("arrays."+format);var transfer=ToolRequest.newBuilder().setKind(ToolKind.EXPORT_RESULT).setResultId(source.id).setPath(output.toString()).setFormat(format).build();
                var export=fixture.jobs.submit(session,UUID.randomUUID().toString(),"",job->transfers.run(job,transfer));EditingIT.await(export);assertEquals(JobState.COMPLETED,export.state,export.info().toString());
                if(format.equals("csv")||format.equals("tsv"))try(var reader=Files.newBufferedReader(output);var csv=(format.equals("csv")?org.apache.commons.csv.CSVFormat.DEFAULT:org.apache.commons.csv.CSVFormat.TDF).builder().setHeader().get().parse(reader)){
                    var record=csv.getRecords().getFirst();for(int i=0;i<expected.size();i++)assertEquals(expected.get(i),record.get(FIELDS.split(",")[i]));
                }else{
                    var json=com.google.gson.JsonParser.parseString(Files.readString(output));var record=format.equals("json")?json.getAsJsonArray().get(0).getAsJsonObject():json.getAsJsonObject();
                    for(int i=0;i<expected.size();i++)assertEquals(expected.get(i),record.get(FIELDS.split(",")[i]).getAsString());
                }
            }
            var row=source.read(0);assertTrue(row.getValues(2).getArray().getNativeLiteral().startsWith("[0:2]"));assertTrue(row.getValues(6).getArray().getNativeLiteral().startsWith("[-1:0][5:6]"));assertTrue(row.getValues(6).getArray().getValues(0).getArray().getValues(1).hasNullValue());assertEquals("12345678901234567890.123456789012",row.getValues(3).getArray().getValues(0).getDecimal());assertArrayEquals(new byte[]{0,(byte)255},row.getValues(5).getArray().getValues(0).getBinary().toByteArray());
            var planner=new ChangePlanner(fixture.safety,fixture.results,fixture.metadata.metadataPlatform());var update=StagedChange.newBuilder().setKind(ChangeKind.UPDATE).setSourceRow(0).putValues(2,Assignments.value(integer(9))).build();
            EditingIT.apply(planner,fixture.jobs,session,request(session,source,update));assertEquals(expected,nativeValues(session,"array_edit",1));
            var clone=planner.cloneRow(session,CloneRowRequest.newBuilder().setSessionId(session.id).setResultId(source.id).setCatalog("busydata").setSchema("public").setTable("array_edit").setSourceRow(0).build());assertEquals(ChangeKind.INSERT,clone.getKind());assertFalse(clone.containsValues(1));assertEquals(row.getValues(2),clone.getValuesOrThrow(3).getValue());
            var cloneRequest=request(session,source,clone);var draft=planner.captureDraft(session,cloneRequest,"array-recovery");assertEquals(row.getValues(2),draft.getRows(0).getRow().getValues(2));
            EditingIT.apply(planner,fixture.jobs,session,cloneRequest);assertEquals(expected,nativeValues(session,"array_edit",2));
            // SQL copy retains the established escaped unknown-string literal contract.
            String copied=SqlCopy.range(source,CopySqlRequest.newBuilder().setFirstRow(0).setRowCount(1).setFirstColumn(2).setColumnCount(7).build());assertFalse(copied.contains("::"));
            fixture.execute(session,"CREATE TABLE array_copy(LIKE array_edit INCLUDING ALL); INSERT INTO array_copy("+FIELDS+") VALUES "+copied);assertEquals(expected,nativeValues(session,"array_copy",1));
            // A concurrent change only to array lower bounds must block the ordinary edit.
            var current=fixture.results.get(fixture.execute(session,"SELECT id,n,"+FIELDS+" FROM "+table+" WHERE id=1").info().getResults(0).getResultId());var changes=request(session,current,update.toBuilder().putValues(2,Assignments.value(integer(11))).build());var plan=planner.preview(session,changes);
            try(var other=DriverManager.getConnection("jdbc:postgresql://"+fixture.database.getHost()+":"+fixture.database.getMappedPort(5432)+"/busydata","busydata","fixture");var statement=other.createStatement()){assertEquals(1,statement.executeUpdate("UPDATE array_edit SET integers='[1:3]={1,NULL,3}'::integer[] WHERE id=1"));}
            var conflict=planner.apply(session,ApplyRequest.newBuilder().setSessionId(session.id).setPlanId(plan.getPlanId()).setExecutionId(UUID.randomUUID().toString()).build(),fixture.jobs);EditingIT.await(conflict);assertEquals(JobState.FAILED,conflict.state);
            try(var statement=session.connection.createStatement();var rows=statement.executeQuery("SELECT n,array_lower(integers,1) FROM array_edit WHERE id=1")){assertTrue(rows.next());assertEquals(9,rows.getInt(1));assertEquals(1,rows.getInt(2));}
        }
    }
    @Test void binaryArraysRetainTheirNativeHeaderAndBindWithoutNormalizingBounds()throws Exception {
        try(var fixture=new EngineFixture(root,"POSTGRESQL")){
            var session=fixture.open();fixture.execute(session,"CREATE TABLE array_binary(id integer PRIMARY KEY,n integer,a integer[]); INSERT INTO array_binary VALUES(1,1,'[-2:0]={1,NULL,3}'::integer[])");
            fixture.warm(session,"array_binary");
            String sql="SELECT id,n,a FROM "+session.adapter.table(session.context.catalog(),"public","array_binary");ResultStore.Result retained=null;
            try(var statement=session.connection.prepareStatement(sql)){
                statement.unwrap(org.postgresql.PGStatement.class).setPrepareThreshold(1);
                // Explicit read invocations exercise the driver's documented prepared threshold.
                for(int invocation=0;invocation<3;invocation++){
                    var snapshot=fixture.metadata.metadataPlatform().capture(session);
                    try(var rows=statement.executeQuery()){
                    assertTrue(rows.next());var array=(org.postgresql.jdbc.PgArray)rows.getArray(3);boolean binary=array.isBinary();array.free();
                    if(invocation==2){assertTrue(binary,"The pinned driver must return the actual binary array format");var columns=Values.columns(rows.getMetaData());retained=fixture.results.create(columns,fixture.profile,session.id,io.busystack.busydata.metadata.RetainedMetadataProof.captureExecution(snapshot,columns,fixture.profile,session.id,sql,session.context));retained.sourceSql=sql;retained.sourceSchema="public";retained.sourceLexical=session.context.lexical();retained.append(Values.row(rows,columns,retained));retained.complete=true;retained.fetchFinished=true;retained.jobState=JobState.COMPLETED;}
                    }
                }
            }
            assertNotNull(retained);var nativeValue=retained.read(0).getValues(2);assertFalse(nativeValue.getArray().getNativeBinary().isEmpty());assertTrue(nativeValue.getArray().getNativeLiteral().isEmpty());ArrayParameters.validate(nativeValue);assertThrows(IllegalArgumentException.class,()->SqlCopy.literal(Engine.POSTGRESQL,nativeValue));
            for(String format:List.of("csv","json")){
                Path output=root.resolve("binary-array."+format);var transfer=ToolRequest.newBuilder().setKind(ToolKind.EXPORT_RESULT).setResultId(retained.id).setPath(output.toString()).setFormat(format).build();var transfers=new io.busystack.busydata.transfers.Transfers(fixture.results);
                var export=fixture.jobs.submit(session,UUID.randomUUID().toString(),"",job->transfers.run(job,transfer));EditingIT.await(export);assertEquals(JobState.FAILED,export.state);assertFalse(Files.exists(output),"Unsupported exact conversion must not publish partial output");
            }
            var planner=new ChangePlanner(fixture.safety,fixture.results,fixture.metadata.metadataPlatform());var changes=ChangeRequest.newBuilder().setSessionId(session.id).setCatalog("busydata").setSchema("public").setTable("array_binary").setResultId(retained.id).addChanges(StagedChange.newBuilder().setKind(ChangeKind.UPDATE).setSourceRow(0).putValues(2,Assignments.value(integer(2)))).build();EditingIT.apply(planner,fixture.jobs,session,changes);
            try(var statement=session.connection.createStatement();var rows=statement.executeQuery("SELECT n,a::text FROM array_binary")){assertTrue(rows.next());assertEquals(2,rows.getInt(1));assertEquals("[-2:0]={1,NULL,3}",rows.getString(2));}
        }
    }
}
